"""Keep credentials out of text that is about to be logged.

**Exception text is not safe to log.** `httpx` puts the URL in its errors, the
push stream's URL carried `api_key=` in the query string, and a log file here
is pasted into issues on a public repo. The transport is being changed to send
the key in a header only, but a URL can reach a log from more than one place
(a library's message, a redirect, a proxy error), so the text is scrubbed at
the point it is written as well.
"""

from __future__ import annotations

import re
from collections.abc import Iterable

MASK = "***"

#: `api_key=...` and its common spellings, in a query string or a body.
_QUERY = re.compile(r"(?i)\b(api[_-]?key|apikey|token|password|secret)=([^&\s'\"]+)")
#: `X-API-Key: ...` as a header line.
_HEADER = re.compile(r"(?i)(x-api-key['\"]?\s*[:=]\s*['\"]?)([^\s,'\"}]+)")
#: `scheme://user:password@host`.
_USERINFO = re.compile(r"(?i)(\b[a-z][a-z0-9+.-]*://)([^/\s:@]+):([^/\s@]+)@")


def redact(text: object, secrets: Iterable[str | None] = ()) -> str:
    """`text` with every credential replaced by `***`.

    `secrets` are exact values to remove wherever they appear - the configured
    API key, which a pattern cannot recognise when it is embedded in a message
    that names it by no label.
    """
    out = str(text)
    out = _QUERY.sub(lambda m: f"{m.group(1)}={MASK}", out)
    out = _HEADER.sub(lambda m: f"{m.group(1)}{MASK}", out)
    out = _USERINFO.sub(lambda m: f"{m.group(1)}{m.group(2)}:{MASK}@", out)
    for secret in secrets:
        if secret and len(str(secret)) >= 4:
            out = out.replace(str(secret), MASK)
    return out
